test('issueInvoice rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  };

  assert.deepEqual(issueInvoice(invoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice rejects already issued invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  };

  assert.deepEqual(issueInvoice(invoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const originalInvoice = JSON.parse(JSON.stringify(r.value));
  issueInvoice(r.value, []);

  assert.deepEqual(r.value, originalInvoice);
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.number, undefined);
});

test('issueInvoice returns new invoice object', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);

  const result1 = issueInvoice(r.value, []);
  const result2 = issueInvoice(r.value, []);

  assert.notEqual(result1.value, result2.value);
  assert.deepEqual(result1.value, result2.value);
});

test('issueInvoice preserves all other invoice properties', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);

  const result = issueInvoice(r.value, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[1].qty, 3);
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice applies tier discount when no discountPercent provided', () => {
  // C-001 is gold tier, so should get 5% discount
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice validates discountPercent is a number', () => {
  const invalidValues = ['10', null, undefined, true];
  for (const val of invalidValues) {
    if (val === undefined) continue; // undefined is ok, it becomes 0
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: val }],
    });
    assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' }, `should reject ${typeof val}`);
  }
});

test('createInvoice validates discountPercent is 0-100', () => {
  const invalidValues = [-0.1, -1, 100.1, 101, 150];
  for (const val of invalidValues) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: val }],
    });
    assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' }, `should reject ${val}`);
  }
});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice accepts 0 and 100 as valid discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(r1.ok, true);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 100 }],
  });
  assert.equal(r2.ok, true);
});

test('lineDiscount calculates discount amount correctly', () => {
  assert.equal(lineDiscount({ qty: 5, unitPrice: 8500, discountPercent: 10 }), 4250); // 5 × 85 × 0.1 = 42.50
  assert.equal(lineDiscount({ qty: 5, unitPrice: 8500, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 5, unitPrice: 8500, discountPercent: 100 }), 42500);
  assert.equal(lineDiscount({ qty: 5, unitPrice: 8500, discountPercent: 50 }), 21250);
});

test('lineDiscount handles decimal discountPercent', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 12.5 }), 1250); // 10 × 10 × 0.125 = 12.50
});

test('lineDiscount defaults discountPercent to 0', () => {
  assert.equal(lineDiscount({ qty: 5, unitPrice: 8500 }), 0);
});

test('lineDiscount is clamped at 0', () => {
  const result = lineDiscount({ qty: 5, unitPrice: 8500, discountPercent: -10 });
  assert.ok(result >= 0);
});

test('invoiceTotals includes subtotal, discount, and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 10 }, // 425.00 - 42.50 = 382.50
      { qty: 3, unitPrice: 9500, discountPercent: 0 }, // 285.00 - 0 = 285.00
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 71000); // 425 + 285 = 710
  assert.equal(totals.discount, 4250); // 42.50
  assert.equal(totals.total, 66750); // 710 - 42.50 = 667.50
});

test('invoiceTotals total = subtotal - discount', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 20 },
      { qty: 3, unitPrice: 9500, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal - totals.discount);
});

test('invoiceTotals total is clamped at 0', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, discountPercent: 150 }, // would be -50
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(totals.total >= 0);
});

test('invoiceTotals with 100% discount', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 100 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with multiple lines, some discounted', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10 }, // 100 - 10 = 90
      { qty: 20, unitPrice: 500, discountPercent: 0 }, // 100 - 0 = 100
      { qty: 5, unitPrice: 2000, discountPercent: 50 }, // 100 - 50 = 50
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000); // 100 + 100 + 100
  assert.equal(totals.discount, 6000); // 10 + 0 + 50
  assert.equal(totals.total, 24000); // 300 - 60
});

