test('createInvoice tier discount affects invoiceTotals', () => {
  // C-001 is gold tier (5%)
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }], // 10 × €85 = €850, 5% discount = €42.50
  });
  assert.equal(r.ok, true);

  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 85000); // €850
  assert.equal(totals.discount, 4250); // €42.50
  assert.equal(totals.total, 80750); // €807.50
});

test('different tiers get different automatic discounts', () => {
  const gold = createInvoice({
    customerId: 'C-001', // gold
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }], // 100 × €85 = €8500
  });
  const silver = createInvoice({
    customerId: 'C-003', // silver
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }], // 100 × €85 = €8500
  });
  const standard = createInvoice({
    customerId: 'C-002', // standard
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }], // 100 × €85 = €8500
  });

  assert.equal(gold.ok, true);
  assert.equal(silver.ok, true);
  assert.equal(standard.ok, true);

  const goldTotals = invoiceTotals(gold.value);
  const silverTotals = invoiceTotals(silver.value);
  const standardTotals = invoiceTotals(standard.value);

  // Gold: 5% discount
  assert.equal(goldTotals.discount, 42500); // €425
  assert.equal(goldTotals.total, 807500); // €8075

  // Silver: 2.5% discount
  assert.equal(silverTotals.discount, 21250); // €212.50
  assert.equal(silverTotals.total, 828750); // €8287.50

  // Standard: 0% discount
  assert.equal(standardTotals.discount, 0);
  assert.equal(standardTotals.total, 850000); // €8500
});

test('lineVAT calculates VAT on amount after discount', () => {
  // Line: 10 × €85 = €850, no discount, 21% VAT = €178.50
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 }), 17850);
  // Line: 10 × €85 = €850, 10% discount = €765, 21% VAT = €160.65
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 }), 16065);
  // 0% VAT
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, vatRate: 0, discountPercent: 0 }), 0);
});

test('lineVAT with different VAT rates', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0 }; // €1000 taxable
  assert.equal(lineVAT({ ...line, vatRate: 21 }), 21000); // €210
  assert.equal(lineVAT({ ...line, vatRate: 9 }), 9000); // €90
  assert.equal(lineVAT({ ...line, vatRate: 0 }), 0);
});

test('lineVAT defaults vatRate to 0', () => {
  assert.equal(lineVAT({ qty: 10, unitPrice: 8500, discountPercent: 0 }), 0);
});

test('lineVAT is clamped at 0', () => {
  const result = lineVAT({ qty: 10, unitPrice: 8500, vatRate: -10, discountPercent: 0 });
  assert.ok(result >= 0);
});

test('invoiceTotals includes vat', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }, // €850, VAT €178.50
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 9 }, // €425, VAT €38.25
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 127500); // €850 + €425
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21675); // €178.50 + €38.25 = €216.75
  assert.equal(totals.total, 149175); // €1275 - 0 + €216.75
});

test('invoiceTotals total = subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }, // €1000, 10% discount €100, 21% on €900 = €189
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals with multiple lines and mixed rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 10000, discountPercent: 5, vatRate: 21 }, // €500 line, €25 discount, €475 taxable, €99.75 VAT
      { qty: 10, unitPrice: 5000, discountPercent: 0, vatRate: 9 }, // €500 line, €500 taxable, €45 VAT
      { qty: 20, unitPrice: 2500, discountPercent: 10, vatRate: 0 }, // €500 line, €50 discount, €450 taxable, €0 VAT
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 150000); // €500 + €500 + €500
  assert.equal(totals.discount, 7500); // €25 + €0 + €50
  assert.equal(totals.vat, 144975); // €99.75 + €45 + €0 = €144.75
  // subtotal €1500 - discount €75 + vat €144.75 = €1569.75
  assert.equal(totals.total, 156975);
});

test('invoiceTotals vat is sum of line VATs, not percentage of total', () => {
  // Create invoice where if VAT were calculated on invoice total, result would be different
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 50, vatRate: 21 }, // €1000, 50% disc €500, €500 taxable, 21% VAT = €105
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }, // €1000, 0% VAT
    ],
  };
  const totals = invoiceTotals(invoice);
  // If VAT were 21% of invoice total: (2000 - 500) * 0.21 = 315
  // But it should be 105 (only on the line with 21% VAT)
  assert.equal(totals.vat, 10500); // €105
  assert.equal(totals.total, 250000 - 50000 + 10500); // €2500 - €500 + €105
});

test('invoiceTotals with 0% VAT lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 6000, discountPercent: 0, vatRate: 0 }, // Workshop day (VAT exempt)
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals vat calculation respects discount', () => {
  // Same product, one with discount, one without
  const withDiscount = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 50, vatRate: 21 }, // €1000, 50% disc = €500, 21% VAT = €105
    ],
  };
  const withoutDiscount = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }, // €1000, 0% disc, 21% VAT = €210
    ],
  };
  const totalsWithDiscount = invoiceTotals(withDiscount);
  const totalsWithoutDiscount = invoiceTotals(withoutDiscount);

  assert.equal(totalsWithDiscount.vat, 10500); // €105
  assert.equal(totalsWithoutDiscount.vat, 21000); // €210
  assert.equal(totalsWithoutDiscount.vat, totalsWithDiscount.vat * 2);
});

