  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: -5 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 101 }), {
    ok: false,
    error: 'DISCOUNT_INVALID',
  });
});

